def Q(c,q,ch,a,sol,w=None): return [c,q,ch,a,w or {},sol]
def X(c,q,right,wrongs,a,sol):
    # right=正解文、wrongs=[(誤答文,つまずきメモ)x3]、a=正解を置く位置
    ch=[t for t,_ in wrongs]; ch.insert(a,right)
    w={i:n for i,(t,n) in zip([i for i in range(4) if i!=a],wrongs)}
    return Q(c,q,ch,a,sol,w)

